import{_ as o,o as a,c as s,a3 as i}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Destinatários do e-mail no memo","description":"","frontmatter":{"title":"Destinatários do e-mail no memo","id":"eproc-memo-destinatarios-email","plataforma":"eproc","grupo":"E-mail","plano":"free","desde":"1.9.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-memo-destinatarios-email"}]]},"headers":[],"relativePath":"funcionalidades/eproc-memo-destinatarios-email.md","filePath":"funcionalidades/eproc-memo-destinatarios-email.md"}'),r={name:"funcionalidades/eproc-memo-destinatarios-email.md"};function n(t,e,l,m,d,c){return a(),s("div",null,e[0]||(e[0]=[i('<h1 id="destinatarios-do-e-mail-no-memo" tabindex="-1">Destinatários do e-mail no memo <a class="header-anchor" href="#destinatarios-do-e-mail-no-memo" aria-label="Permalink to &quot;Destinatários do e-mail no memo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Depois que você envia um e-mail pela tela do processo, o eproc lança um evento com o documento <strong>EMAIL1</strong>, sem memo. A extensão preenche o memo desse documento com a linha <strong>Para:</strong> do e-mail. Assim, a tabela de eventos mostra para quem o e-mail foi, sem precisar abri-lo.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela do processo, no memo do documento EMAIL do evento criado pelo envio.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo e vá à tela de envio de e-mail.</li><li>Escreva e envie o e-mail normalmente.</li><li>Volte à tela do processo. Quando o novo evento aparece, a extensão grava o memo em segundo plano. Um pequeno ícone de arroba ao lado do documento indica que o memo foi preenchido.</li><li>Recarregue a página para ver o memo exibido pelo próprio eproc.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só os e-mails enviados por você, neste navegador, nos últimos 30 minutos são tratados. Memos de e-mails antigos ou enviados por outras pessoas não são alterados.</li><li>Se o documento já tiver memo, ele é mantido como está.</li></ul>',11)]))}const h=o(r,[["render",n]]);export{u as __pageData,h as default};
